"""OpenAI-compatible chat client with retries, usage logging and a hard token budget.

One JSON response per request (no SSE: the platform meter once summed streamed usage
chunks). Account errors (401/402/403, insufficient balance) stop the run instead of
retrying. Thread-safe so spec generation can run requests in parallel.
"""
from __future__ import annotations

import json
import os
import ssl
import threading
import time
import urllib.error
import urllib.request
from dataclasses import dataclass
from pathlib import Path

from factory.prompts import guide_model_messages


class BudgetExhausted(RuntimeError):
    """The run's token budget is spent; stop issuing new requests."""


class ProviderFatal(RuntimeError):
    """Account or configuration failure; retrying cannot help."""


class ProviderUnavailable(ProviderFatal):
    """Transient failures used up every attempt; a caller may still try differently."""


@dataclass
class Reply:
    text: str
    finish_reason: str
    prompt_tokens: int
    completion_tokens: int
    reasoning_tokens: int
    cached_tokens: int
    seconds: float

    @property
    def truncated(self) -> bool:
        return self.finish_reason == "length"


FATAL_TERMS = ("insufficient_balance", "quota exhausted", "balance is exhausted", "invalid_api_key",
               "authentication failed", "unauthorized", "model_cooldown")
TRANSIENT_400_TERMS = ("proxy_error", "unexpected eof", "upstream connection", "connection reset",
                       "temporarily unavailable", "gateway timeout")


def ssl_context() -> ssl.SSLContext:
    """Default verification, plus a CA bundle when the interpreter ships none (python.org macOS builds)."""
    ctx = ssl.create_default_context()
    if ctx.cert_store_stats().get("x509_ca", 0):
        return ctx
    candidates = [os.environ.get("SSL_CERT_FILE", "")]
    try:
        import certifi  # type: ignore
        candidates.append(certifi.where())
    except ImportError:
        pass
    candidates += ["/etc/ssl/cert.pem", "/etc/ssl/certs/ca-certificates.crt", "/etc/pki/tls/certs/ca-bundle.crt"]
    for path in candidates:
        if path and Path(path).is_file():
            return ssl.create_default_context(cafile=path)
    return ctx


class LLM:
    def __init__(self, usage_path: Path, log, max_total_tokens: int = 0):
        self.base_url = os.environ.get("OPENAI_BASE_URL", "").rstrip("/")
        self.api_key = os.environ.get("OPENAI_API_KEY", "")
        self.model = os.environ.get("MODEL", "deepseek-v4-flash")
        self.user_agent = os.environ.get(
            "ARC_LLM_USER_AGENT",
            "Mozilla/5.0 ARC-Bench-Agent/1.0",
        )
        self.usage_path = usage_path
        self.log = log
        self.max_total_tokens = max_total_tokens
        self.timeout = int(os.environ.get("ARC_LLM_TIMEOUT", "900"))
        self.max_output = int(os.environ.get("ARC_MAX_OUTPUT_TOKENS", "64000"))
        self._lock = threading.Lock()
        self.ssl = ssl_context()
        self.prompt_tokens = 0
        self.completion_tokens = 0
        self.reasoning_tokens = 0
        self.cached_tokens = 0
        self.requests = 0
        usage_path.parent.mkdir(parents=True, exist_ok=True)

    @property
    def total_tokens(self) -> int:
        return self.prompt_tokens + self.completion_tokens

    def remaining(self) -> int:
        if not self.max_total_tokens:
            return 1 << 62
        return self.max_total_tokens - self.total_tokens

    def _body(self, messages: list[dict], reasoning: str, max_tokens: int,
              analysis_bridge: bool = False) -> dict:
        # ARC_LLM_STREAM=1 is for local networks that cut long idle TLS connections; the platform keeps
        # one JSON response (its meter once summed streamed usage chunks).
        stream = os.environ.get("ARC_LLM_STREAM") == "1"
        guided_messages = guide_model_messages(
            self.model,
            messages,
            analysis_bridge=analysis_bridge,
        )
        body: dict = {"model": self.model, "messages": guided_messages,
                      "max_tokens": max_tokens, "stream": stream}
        if stream:
            body["stream_options"] = {"include_usage": True}
        model = self.model.lower()
        if "deepseek" in model:
            if reasoning in ("none", "off"):
                body["thinking"] = {"type": "disabled"}
            else:
                body["thinking"] = {"type": "enabled"}
                body["reasoning_effort"] = reasoning
        elif any(k in model for k in ("qwen", "glm", "kimi", "minimax")):
            # These gateways accept enable_thinking; a disabled flag keeps codegen replies lean.
            body["enable_thinking"] = reasoning not in ("none", "off")
        if reasoning in ("none", "off"):
            body["temperature"] = 0.2
        return body

    def _chat_claude_cli(self, messages: list[dict], label: str, reasoning: str, attempts: int) -> Reply:
        """Local testing backend (ARC_LLM_BACKEND=claude-cli): one `claude -p` call per request, tools off,
        using the machine's logged-in Claude Code account. Never used on the platform."""
        import subprocess
        import tempfile
        system = "\n\n".join(m["content"] for m in messages if m["role"] == "system")
        turns = [m for m in messages if m["role"] != "system"]
        if len(turns) == 1:
            prompt = turns[0]["content"]
        else:
            prompt = "\n\n".join(f"[{m['role'].upper()}]\n{m['content']}" for m in turns) + \
                "\n\n[Answer the last USER message.]"
        model = os.environ.get("ARC_CLAUDE_MODEL", "claude-sonnet-5")
        cmd = [os.environ.get("ARC_CLAUDE_BIN", "claude"), "-p", "--output-format", "json", "--tools", "",
               "--model", model, "--no-session-persistence", "--system-prompt", system or "You are a helpful assistant."]
        effort = {"none": "low", "off": "low", "low": "low", "medium": "medium", "high": "high"}.get(reasoning)
        if effort and os.environ.get("ARC_CLAUDE_EFFORT", "1") == "1":
            cmd += ["--effort", effort]
        last_error = ""
        for attempt in range(1, attempts + 1):
            t0 = time.time()
            try:
                r = subprocess.run(cmd, input=prompt, capture_output=True, text=True, timeout=self.timeout,
                                   cwd=tempfile.gettempdir())
                data = json.loads(r.stdout or "{}")
            except (subprocess.TimeoutExpired, json.JSONDecodeError, OSError) as exc:
                last_error = f"{type(exc).__name__}: {str(exc)[:200]}"
                data = None
            if data is not None:
                text = str(data.get("result") or "")
                if data.get("is_error"):
                    last_error = text[:300] or (r.stderr or "")[:300]
                    if any(t in last_error.lower() for t in ("authenticate", "oauth", "login", "api key", "credit", "quota")):
                        raise ProviderFatal(f"claude CLI: {last_error}")
                else:
                    usage = data.get("usage") or {}
                    payload = {
                        "choices": [{"message": {"content": text},
                                     "finish_reason": "length" if data.get("stop_reason") == "max_tokens" else "stop"}],
                        "usage": {"prompt_tokens": int(usage.get("input_tokens") or 0)
                                  + int(usage.get("cache_read_input_tokens") or 0)
                                  + int(usage.get("cache_creation_input_tokens") or 0),
                                  "completion_tokens": int(usage.get("output_tokens") or 0),
                                  "prompt_tokens_details": {"cached_tokens": int(usage.get("cache_read_input_tokens") or 0)}},
                    }
                    return self._record(payload, label, time.time() - t0)
            wait = min(90, 15 * 2 ** (attempt - 1))
            self.log(f"[llm] {label}: claude CLI attempt {attempt} failed ({last_error[:200]}); retry in {wait}s")
            if attempt < attempts:
                time.sleep(wait)
        raise RuntimeError(f"claude CLI request {label} failed after {attempts} attempts: {last_error[:300]}")

    def _chat_codex_cli(self, messages: list[dict], label: str, reasoning: str, attempts: int) -> Reply:
        import subprocess
        import tempfile

        prompt = "\n\n".join(f"[{message['role'].upper()}]\n{message['content']}" for message in messages)
        effort = {"none": "low", "off": "low", "low": "low", "medium": "medium", "high": "high"}.get(
            reasoning, "medium")
        last_error = ""
        for attempt in range(1, attempts + 1):
            started = time.time()
            with tempfile.TemporaryDirectory(prefix="factory-codex-") as temporary_dir:
                output_path = Path(temporary_dir) / "reply.txt"
                command = [os.environ.get("ARC_CODEX_BIN", "codex"), "exec", "-m", self.model, "--json",
                           "-s", "read-only", "--skip-git-repo-check", "--ephemeral", "--ignore-user-config",
                           "-C", temporary_dir, "--output-last-message", str(output_path),
                           "-c", f'model_reasoning_effort="{effort}"', "-"]
                try:
                    result = subprocess.run(command, input=prompt, capture_output=True, text=True,
                                            timeout=self.timeout, cwd=temporary_dir)
                    reply_text = output_path.read_text(encoding="utf-8") if output_path.exists() else ""
                    events = [json.loads(line) for line in result.stdout.splitlines() if line.startswith("{")]
                    usage = next((event.get("usage") or {} for event in reversed(events)
                                  if event.get("type") == "turn.completed"), {})
                    if result.returncode == 0 and reply_text and usage:
                        payload = {
                            "choices": [{"message": {"content": reply_text}, "finish_reason": "stop"}],
                            "usage": {"prompt_tokens": usage.get("input_tokens", 0),
                                      "completion_tokens": usage.get("output_tokens", 0),
                                      "prompt_tokens_details": {"cached_tokens": usage.get("cached_input_tokens", 0)},
                                      "completion_tokens_details": {"reasoning_tokens":
                                                                    usage.get("reasoning_output_tokens", 0)}}}
                        return self._record(payload, label, time.time() - started)
                    last_error = f"exit={result.returncode} reply={len(reply_text)} usage={bool(usage)} " \
                                 f"{result.stderr[-250:]}"
                except (OSError, subprocess.TimeoutExpired, UnicodeError, json.JSONDecodeError) as error:
                    last_error = f"{type(error).__name__}: {str(error)[:250]}"
            self.log(f"[llm] {label}: codex CLI attempt {attempt} failed ({last_error[:250]})")
            if attempt < attempts:
                time.sleep(min(60, 10 * attempt))
        raise RuntimeError(f"codex CLI request {label} failed after {attempts} attempts: {last_error[:300]}")

    def chat(self, messages: list[dict], *, label: str, reasoning: str = "none",
             max_tokens: int | None = None, attempts: int = 4,
             analysis_bridge: bool = False, max_wait: int | None = None,
             attempt_timeout: int | None = None) -> Reply:
        if self.remaining() <= 0:
            raise BudgetExhausted(f"token budget {self.max_total_tokens} spent")
        if os.environ.get("ARC_LLM_BACKEND") == "claude-cli":
            return self._chat_claude_cli(messages, label, reasoning, attempts)
        if os.environ.get("ARC_LLM_BACKEND") == "codex-cli":
            return self._chat_codex_cli(messages, label, reasoning, attempts)
        if not self.base_url.startswith("http"):
            raise ProviderFatal("OPENAI_BASE_URL is not set")
        effective_max_tokens = min(max_tokens or self.max_output, self.remaining())
        body = self._body(
            messages,
            reasoning,
            effective_max_tokens,
            analysis_bridge=analysis_bridge,
        )
        data = json.dumps(body, ensure_ascii=False).encode("utf-8")
        url = f"{self.base_url}/chat/completions"
        last_error = ""
        started = time.time()
        if max_wait is None:
            max_wait = int(os.environ.get("ARC_LLM_MAX_WAIT", "300"))
        max_wait = max(0, max_wait)
        attempt = 0
        while True:
            elapsed = time.time() - started
            if attempt and max_wait and elapsed >= max_wait:
                break
            attempt += 1
            request_timeout = self.timeout
            if attempt_timeout:
                request_timeout = min(request_timeout, attempt_timeout)
            if max_wait:
                request_timeout = max(1, min(request_timeout, max_wait - elapsed))
            t0 = time.time()
            req = urllib.request.Request(url, data=data, method="POST", headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
                "User-Agent": self.user_agent,
            })
            try:
                with urllib.request.urlopen(req, timeout=request_timeout, context=self.ssl) as resp:
                    payload = self._read_stream(resp) if body.get("stream") else json.loads(resp.read().decode("utf-8"))
                return self._record(payload, label, time.time() - t0)
            except urllib.error.HTTPError as exc:
                detail = exc.read().decode("utf-8", "replace")[:600]
                exc.close()
                last_error = f"HTTP {exc.code}: {detail}"
                detail_lower = detail.lower()
                if exc.code in (401, 402, 403) or any(t in detail_lower for t in FATAL_TERMS):
                    raise ProviderFatal(last_error) from exc
                if exc.code == 400 and "context" in detail_lower:
                    raise ProviderFatal(last_error) from exc
                retryable_400 = exc.code == 400 and any(term in detail_lower for term in TRANSIENT_400_TERMS)
                if not retryable_400 and exc.code not in (408, 409, 425, 429, 500, 502, 503, 504, 520, 522, 524):
                    raise ProviderFatal(last_error) from exc
            except (urllib.error.URLError, TimeoutError, ConnectionError, OSError, json.JSONDecodeError) as exc:
                last_error = f"{type(exc).__name__}: {exc}"
            elapsed = time.time() - started
            if attempt >= attempts or (max_wait and elapsed >= max_wait):
                break
            wait = min(60, 15 * 2 ** min(attempt - 1, 3))
            if max_wait:
                wait = min(wait, max_wait - elapsed)
            if wait <= 0:
                break
            self.log(f"[llm] {label}: attempt {attempt} failed ({last_error[:200]}); retry in {wait}s "
                     f"({int(elapsed)}s of {max_wait}s retry window used)")
            time.sleep(wait)
        raise ProviderUnavailable(f"model request {label} failed after {attempt} attempts / "
                                  f"{int(time.time() - started)}s: {last_error[:300]}")

    @staticmethod
    def _read_stream(resp) -> dict:
        """Collapse an SSE chat stream into the non-streaming response shape. Usage comes from
        the final chunk only (stream_options.include_usage), never summed across chunks."""
        parts: list[str] = []
        finish = ""
        usage: dict = {}
        for raw in resp:
            line = raw.decode("utf-8", "replace").strip()
            if not line.startswith("data:"):
                continue
            data = line[5:].strip()
            if data == "[DONE]":
                break
            try:
                chunk = json.loads(data)
            except json.JSONDecodeError:
                continue
            if chunk.get("usage"):
                usage = chunk["usage"]
            for choice in chunk.get("choices") or []:
                delta = choice.get("delta") or {}
                if delta.get("content"):
                    parts.append(delta["content"])
                if choice.get("finish_reason"):
                    finish = choice["finish_reason"]
        if not finish:
            # The connection dropped mid-stream: a partial reply is not a reply.
            raise ConnectionError(f"stream ended without a finish reason after {len(''.join(parts))} chars")
        return {"choices": [{"message": {"content": "".join(parts)}, "finish_reason": finish}], "usage": usage}

