def env_int(name: str, default: int) -> int:
    try:
        return int(os.environ.get(name, default))
    except ValueError:
        return default


def candidate_spec_files(reference: acc.RunSummary, target_files: list[str]) -> list[str]:
    targets = list(dict.fromkeys(target_files))
    guards = sorted({result.file for result in reference.results if result.ok and result.file
                     and result.file not in targets})
    return targets + guards


def candidate_improves(reference: acc.RunSummary, trial: acc.RunSummary, target_files: set[str]) -> bool:
    if trial.error or trial.timed_out or trial.killed or not trial.results:
        return False
    previous = {(result.file, result.title): result for result in reference.results}
    current = {(result.file, result.title): result for result in trial.results}
    required = {key for key, result in previous.items() if result.ok or result.file in target_files}
    if not required or not required.issubset(current):
        return False
    if any(not current[key].ok for key in required if previous[key].ok):
        return False
    before = sum(result.ok for result in reference.results if result.file in target_files)
    after = sum(result.ok for result in trial.results if result.file in target_files)
    return after > before


def guard_regressions(reference: acc.RunSummary, trial: acc.RunSummary,
                      guard_files: list[str]) -> list[acc.TestOutcome]:
    if trial.error or trial.timed_out or trial.killed or not trial.results:
        return []
    files = set(guard_files)
    previous = {(result.file, result.title): result for result in reference.results
                if result.ok and result.file in files}
    current = {(result.file, result.title): result for result in trial.results}
    if not previous or not set(previous).issubset(current):
        return []
    return [current[key] for key in previous if not current[key].ok]


def seeded_result_preserves(reference: acc.RunSummary, trial: acc.RunSummary) -> bool:
    if trial.error or trial.timed_out or trial.killed or not trial.results:
        return False
    previous = {(result.file, result.title): result for result in reference.results}
    current = {(result.file, result.title): result for result in trial.results}
    if not set(previous).issubset(current):
        return False
    return not any(result.ok and not current[key].ok for key, result in previous.items())


def final_retry_files(reference: acc.RunSummary, trial: acc.RunSummary,
                      spec_files: list[str], titles_by_file: dict[str, list[str]]) -> list[str]:
    previous = {(result.file, result.title): result for result in reference.results}
    current = {(result.file, result.title): result for result in trial.results}
    retry = set()
    missing = set()
    for key, result in previous.items():
        if result.ok and (key not in current or not current[key].ok):
            retry.add(key[0])
    for file_name in spec_files:
        if any((file_name, title) not in current for title in titles_by_file.get(file_name, [])):
            missing.add(file_name)
    retry.update(missing)
    if (trial.error or trial.timed_out or trial.killed) and not missing:
        retry.update(spec_files)
    return [file_name for file_name in spec_files if file_name in retry]


def repair_batch_order(failures: dict[int, list], limit: int) -> list[int]:
    ordered = sorted(failures, key=lambda index: (-len(failures[index]), index))
    return ordered if limit <= 0 else ordered[:limit]


class Logger:
    def __init__(self, path: Path):
        self.path = path
        self.lock = threading.Lock()
        self.to_stderr = bool(os.environ.get("ARCBENCH_TASK_DIR") or os.environ.get("ARCBENCH_OUTPUT_DIR"))

    def __call__(self, msg: str) -> None:
        line = f"[{time.strftime('%H:%M:%S')}] {msg}"
        with self.lock:
            print(line, flush=True)
            if self.to_stderr:
                print(line, file=sys.stderr, flush=True)
            try:
                with self.path.open("a", encoding="utf-8") as fh:
                    fh.write(line + "\n")
            except OSError:
                pass


class Engine:
    def __init__(self, req_dir: Path, output_dir: Path, web_port: int = 3000):
        self.out = output_dir
        self.arc = output_dir / ".arc"
        self.arc.mkdir(parents=True, exist_ok=True)
        self.log = Logger(self.arc / "factory.log")
        self.tree = Tree.load(req_dir)
        self.batches = self.tree.batches(max_nodes=env_int("ARC_BATCH_NODES", 4), max_chars=env_int("ARC_BATCH_CHARS", 9000))
        cap = env_int("ARC_MAX_BATCHES", 0)
        if cap:
            self.batches = self.batches[:cap]
        n = len(self.tree.atomic)
        self.t0 = time.time()
        self.deadline = self.t0 + env_int("ARC_TIME_BUDGET", max(3600, 330 * n))
        self.llm = LLM(self.arc / "llm-usage.jsonl", self.log,
                       max_total_tokens=env_int("ARC_MAX_TOKENS", max(8_000_000, 400_000 * n)))
        self.tests_dir = self.arc / "acceptance"
        self.web_port = web_port
        port = env_int("ARC_TEST_PORT", 3187)
        self.port = port if port != web_port else port + 1
        self.runtime = AgentRuntime.from_env(project_dir=str(output_dir))
        self.events = self.runtime.events
        self.git = self.runtime.git
        self.plan = ""
        self.app_support = ""
        self.spec_of: dict[str, str] = {}          # node id -> spec file name
        self.last: dict[str, bool] = {}            # test title -> last observed ok
        self.best_total = -1
        self.best_commit: str | None = None
        self.runner: acc.AcceptanceRunner | None = None
        self.phase = "init"
        self.seeded = False
        self.seeded_titles: dict[str, list[str]] = {}
        self.repair_feedback: dict[str, list[str]] = {}
        self._stop_heartbeat = threading.Event()

    # ------------------------------------------------------------------ infra
    def time_left(self) -> float:
        return self.deadline - time.time()

    def seeded_fast_path_enabled(self) -> bool:
        return self.seeded and os.environ.get("ARC_SEEDED_OPTIMIZE", "0") != "1"

    def heartbeat(self) -> None:
        while not self._stop_heartbeat.wait(30):
            self.log(f"[heartbeat] phase={self.phase} elapsed={int(time.time() - self.t0)}s "
                     f"tokens={self.llm.total_tokens} best={self.best_total}")

    def sh_git(self, *args: str) -> subprocess.CompletedProcess:
        return subprocess.run(["git", "-C", str(self.out), *args], capture_output=True, text=True)

    def commit(self, message: str, *, required: bool = False) -> str | None:
        try:
            self.git.commit(message)
        except Exception as exc:  # noqa: BLE001
            self.log(f"[git] commit failed: {exc}")
            if required:
                raise
        head = self.git.current_head()
        if required and not head:
            raise RuntimeError("git commit produced no HEAD")
        return head

    def revert_to(self, commit: str | None) -> None:
        normalized = str(commit or "").strip()
        if not normalized:
            raise ValueError("commit is required")
        self.git.reset_to_commit(normalized)
        self.git.run(["clean", "-fdq", "--", "frontend", "backend"])

    def setup(self) -> None:
        self.phase = "setup"
        self.log(f"[factory] {len(self.tree.atomic)} atomic requirements, {len(self.batches)} batches; "
